package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class PlaneGeometrySvgRenderer { public String render(PlaneGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(PlaneGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding();StringBuilder b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(s.viewport().width()-2*p).append("\" height=\"").append(s.viewport().height()-2*p).append("\" fill=\"none\" stroke=\"#000000\"/>");Map<String,int[]> points=new HashMap<>();for(var point:s.points()){int x=p+20,y=p+20;points.put(point.pointKey(),new int[]{x,y});b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"3\" fill=\"#000000\"/>");}for(var seg:s.segments()){int[] a=points.get(seg.startPointKey()),c=points.get(seg.endPointKey());if(a!=null&&c!=null)b.append("<line x1=\"").append(a[0]).append("\" y1=\"").append(a[1]).append("\" x2=\"").append(c[0]).append("\" y2=\"").append(c[1]).append("\" stroke=\"#000000\"/>");}for(var circle:s.circles()){int[] c=points.get(circle.centerPointKey());if(c!=null)b.append("<circle cx=\"").append(c[0]).append("\" cy=\"").append(c[1]).append("\" r=\"20\" fill=\"none\" stroke=\"#000000\"/>");}for(var arc:s.arcs()){int[] c=points.get(arc.centerPointKey());if(c!=null)b.append("<path d=\"M ").append(c[0]+20).append(" ").append(c[1]).append(" A 20 20 0 0 1 ").append(c[0]).append(" ").append(c[1]-20).append("\" fill=\"none\" stroke=\"#000000\"/>");}for(var angle:s.angles()){int[] c=points.get(angle.vertexPointKey());if(c!=null)b.append("<path d=\"M ").append(c[0]+12).append(" ").append(c[1]).append(" A 12 12 0 0 1 ").append(c[0]).append(" ").append(c[1]-12).append("\" fill=\"none\" stroke=\"#000000\"/>");}for(var m:s.measurements())b.append("<text x=\"").append(p+8).append("\" y=\"").append(p+18).append("\">").append(escape(m.labelTemplate())).append("</text>");return b.toString();}private String escape(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
